style.css:
@-moz-document domain("roblox.com") {
/* Global Background & Variables */
    body, 
    html, 
    .light-theme, 
    .dark-theme,
    [class*="theme"] {
        background-image: linear-gradient(rgba(10, 15, 12, 0.7), rgba(10, 15, 12, 0.7)), url("https://i.pinimg.com/736x/78/46/82/784682faa8a089235ff79a5067390de9.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-color: transparent !important;
        --color-surface-base: transparent !important;
        --color-background: transparent !important;
        --color-default: #ffffff !important;
    }

    /* Cards, Containers, Navigation, and Sidebars with a "Chill" Rounded Layout */
    .content, 
    #header, 
    .rbx-left-col, 
    .game-card-container, 
    .section-content, 
    .rbx-tabs-horizontal,
    .modal-content,
    .card-item,
    .popover-content,
    .dropdown-menu,
    .rbx-header,
    .container-main,
    .grid-item,
    div[class*="card"],
    div[class*="container"],
    div[class*="menu"],
    div[class*="sidebar"] {
        background-color: rgba(20, 32, 24, 0.82) !important;
        backdrop-filter: blur(12px) !important;
        -webkit-backdrop-filter: blur(12px) !important;
        border: 1px solid rgba(110, 168, 254, 0.25) !important;
        border-radius: 12px !important;
        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4) !important;
    }

    /* Header & Navigation Polish */
    .rbx-header, #header {
        border-bottom: 1px solid rgba(110, 168, 254, 0.2) !important;
        border-radius: 0 0 16px 16px !important;
    }

    /* Remove Harsh Boxy Backgrounds on Inner Lists/Rows */
    .container-list, 
    .item-card, 
    .game-card,
    .section {
        background: transparent !important;
    }

    /* Primary Text */
    body, 
    p, 
    span, 
    h1, 
    h2, 
    h3, 
    h4, 
    h5, 
    h6, 
    label, 
    input,
    textarea,
    .text-date-hint, 
    .font-header-2,
    [class*="text"] {
        color: #ffffff !important;
    }

    /* Secondary Text and Links */
    a, 
    a:hover, 
    a:focus, 
    .text-link, 
    .text-name,
    .font-body,
    span[class*="text-"],
    a[class*="text-"] {
        color: #a3c6ff !important;
    }

    /* Primary Buttons (Play Button, etc.) with Chill Rounded Look */
    .btn-primary-md, 
    .btn-primary-lg, 
    .btn-full-width, 
    button.btn-primary, 
    .rbx-btn-primary-lg,
    button[class*="btn-primary"] {
        background-color: #4a7c36 !important;
        border-color: #4a7c36 !important;
        border-radius: 10px !important;
        color: #ffffff !important;
        box-shadow: 0 4px 12px rgba(74, 124, 54, 0.35) !important;
        transition: all 0.2s ease !important;
    }

    .btn-primary-md:hover, 
    .btn-primary-lg:hover, 
    button.btn-primary:hover, 
    .rbx-btn-primary-lg:hover,
    button[class*="btn-primary"]:hover {
        background-color: #558e3f !important;
        border-color: #558e3f !important;
        transform: translateY(-1px) !important;
        color: #ffffff !important;
    }

    /* Secondary / Neutral Buttons */
    .btn-control-md, 
    .btn-control-lg,
    button[class*="btn-control"] {
        background-color: rgba(30, 48, 36, 0.8) !important;
        border: 1px solid rgba(110, 168, 254, 0.3) !important;
        border-radius: 10px !important;
        color: #ffffff !important;
    }
}
